@startuml

class OilWell {
  + code : string
}

class OnshoreWell extends OilWell {
  + surfaceExtension : float
}

class OffshoreWell extends OilWell {
  + yearOfInstallation : int
  + areaCode : string
}

class Company {
  + taxCode : string
  + numberOfEmployees : int
}

class GeographicalArea {
  + code : string
  + environmentalImportance : int
}

class Extraction {
  + quantity : float
}

OilWell "0..*" -- "0..*" Company : extraction
Extraction "1" -- "1" OilWell
Extraction "1" -- "1" Company

OffshoreWell "0..*" -- "0..1" GeographicalArea

@enduml

